-- 012: Web push. Every row inserted into public.notifications is also delivered as a push
-- notification to the member's subscribed browsers/devices by the `send-push` Edge Function.
-- Secrets live in Supabase Vault: the VAPID key pair (generated by the Edge Function on first
-- run) and the trigger→function shared secret (generated here). Nothing secret is in the repo.

-- pg_net's functions always live in the `net` schema; register the extension under `extensions`.
CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;

-- ─── Subscriptions ───────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.push_subscriptions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users (id) ON DELETE CASCADE,
  endpoint text NOT NULL UNIQUE,
  p256dh text NOT NULL,
  auth text NOT NULL,
  user_agent text,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz
);
CREATE INDEX IF NOT EXISTS push_subscriptions_user_idx ON public.push_subscriptions (user_id);

ALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS push_subscriptions_owner_select ON public.push_subscriptions;
CREATE POLICY push_subscriptions_owner_select ON public.push_subscriptions
  FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
-- Writes go through the RPCs below (a device can move between accounts on the same endpoint).
REVOKE INSERT, UPDATE, DELETE ON public.push_subscriptions FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.save_push_subscription(
  p_endpoint text, p_p256dh text, p_auth text, p_user_agent text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in.' USING ERRCODE = '42501'; END IF;
  IF p_endpoint !~ '^https://' OR length(p_endpoint) > 2048 THEN RAISE EXCEPTION 'Invalid endpoint.'; END IF;
  INSERT INTO public.push_subscriptions (user_id, endpoint, p256dh, auth, user_agent)
  VALUES (auth.uid(), p_endpoint, p_p256dh, p_auth, left(p_user_agent, 300))
  ON CONFLICT (endpoint) DO UPDATE
    SET user_id = EXCLUDED.user_id, p256dh = EXCLUDED.p256dh, auth = EXCLUDED.auth,
        user_agent = EXCLUDED.user_agent, created_at = now();
  RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION public.delete_push_subscription(p_endpoint text)
RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  WITH d AS (DELETE FROM public.push_subscriptions WHERE endpoint = p_endpoint AND user_id = auth.uid() RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM d);
$$;

-- ─── Vault-backed configuration ──────────────────────────────────────────────
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM vault.secrets WHERE name = 'push_webhook_secret') THEN
    PERFORM vault.create_secret(
      replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),
      'push_webhook_secret',
      'Shared secret between the notifications trigger and the send-push Edge Function');
  END IF;
END $$;

-- Public key for PushManager.subscribe (NULL until the Edge Function has generated the pair).
CREATE OR REPLACE FUNCTION public.get_vapid_public_key()
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'push_vapid_public';
$$;

-- Edge Function only (service_role).
CREATE OR REPLACE FUNCTION public.push_service_config()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object(
    'public_key', (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'push_vapid_public'),
    'private_key', (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'push_vapid_private'),
    'webhook_secret', (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'push_webhook_secret'));
$$;

-- Edge Function only: stores the generated VAPID pair once (first writer wins).
CREATE OR REPLACE FUNCTION public.store_push_vapid_keys(p_public text, p_private text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('push_vapid_keys'));
  IF NOT EXISTS (SELECT 1 FROM vault.secrets WHERE name = 'push_vapid_private') THEN
    PERFORM vault.create_secret(p_private, 'push_vapid_private', 'Web push VAPID private key');
    PERFORM vault.create_secret(p_public, 'push_vapid_public', 'Web push VAPID public key');
  END IF;
END;
$$;

-- ─── Trigger: hand each new notification to the Edge Function ───────────────
CREATE OR REPLACE FUNCTION public.enqueue_push_notification()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_secret text;
BEGIN
  IF NEW.user_id IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.push_subscriptions WHERE user_id = NEW.user_id) THEN
    RETURN NEW;
  END IF;
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'push_webhook_secret';
  PERFORM net.http_post(
    url := 'https://hgucqabzlaxelkfiavvm.supabase.co/functions/v1/send-push',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', v_secret),
    body := jsonb_build_object('notification', jsonb_build_object(
      'id', NEW.id, 'user_id', NEW.user_id, 'type', NEW.type, 'title', NEW.title,
      'message', NEW.message, 'action_url', NEW.action_url)),
    timeout_milliseconds := 5000);
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Push is best-effort; never block the notification itself.
  RAISE WARNING 'enqueue_push_notification: %', SQLERRM;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notifications_push ON public.notifications;
CREATE TRIGGER trg_notifications_push AFTER INSERT ON public.notifications
  FOR EACH ROW EXECUTE FUNCTION public.enqueue_push_notification();

-- ─── Grants ──────────────────────────────────────────────────────────────────
REVOKE EXECUTE ON FUNCTION public.save_push_subscription(text, text, text, text),
  public.delete_push_subscription(text), public.get_vapid_public_key(),
  public.push_service_config(), public.store_push_vapid_keys(text, text),
  public.enqueue_push_notification()
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.save_push_subscription(text, text, text, text),
  public.delete_push_subscription(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_vapid_public_key() TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.push_service_config(), public.store_push_vapid_keys(text, text) TO service_role;
